    OR EXISTS (SELECT 1 FROM authz_int."folder__view" v WHERE v.id = o."folder_id"))))
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    ELSE
      RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
  END CASE;
END $f$;

-- Every object the user holds a permission on, whether they may select its row or not: what the access previews
-- (rowstile diff, the review's access, rowstile snapshot) list, run as the owner. authz.list where it is the same
CREATE OR REPLACE FUNCTION authz_int.list(p_type text, p_perm text) RETURNS SETOF text
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
  IF NOT authz_int.scope_perm(p_type, p_perm) THEN RETURN; END IF;
  CASE p_type || '.' || p_perm
    WHEN 'folder.break_glass' THEN
      RETURN QUERY SELECT o."id"::text FROM "app"."folders" o
        WHERE EXISTS (SELECT 1 FROM authz_int."org__member" v WHERE v.id = o."org_id");
    WHEN 'file.comment' THEN
      RETURN QUERY SELECT o."id"::text FROM "app"."files" o
        WHERE (EXISTS (SELECT 1 FROM authz_int."folder__share__direct" v WHERE v.id = o."folder_id")
    OR EXISTS (SELECT 1 FROM authz_int."folder__view" v WHERE v.id = o."folder_id"));
    ELSE
      RETURN QUERY SELECT * FROM authz.list(p_type, p_perm);
  END CASE;
END $f$;

-- Every permission the user holds on one object: SELECT authz.perms('file', 11)
CREATE OR REPLACE FUNCTION authz.perms(p_type text, p_id text) RETURNS text[]
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE names text[];
BEGIN
  CASE p_type
    WHEN 'user' THEN names := ARRAY['impersonate']::text[];
    WHEN 'org' THEN names := ARRAY[]::text[];
    WHEN 'team' THEN names := ARRAY[]::text[];
    WHEN 'folder' THEN names := ARRAY['share', 'edit', 'view', 'break_glass']::text[];
    WHEN 'file' THEN names := ARRAY['share', 'comment', 'edit', 'view']::text[];
    ELSE RAISE EXCEPTION 'no type % in the policy', p_type USING HINT = 'rowstile help AZ707';
  END CASE;
  RETURN ARRAY(SELECT n FROM unnest(names) n WHERE authz.can(p_type, p_id, n));
END $f$;

CREATE FUNCTION authz_int."file__comment__who"(p_id bigint) RETURNS SETOF bigint
LANGUAGE sql STABLE STRICT SECURITY DEFINER SET search_path FROM CURRENT ROWS 50 AS $f$
  SELECT x FROM (SELECT r."folder_id" AS id FROM "app"."files" r WHERE r."id" = p_id AND r."folder_id" IS NOT NULL) tg, LATERAL authz_int."folder__view__who"(tg.id) x
$f$;

CREATE FUNCTION authz_int."file__comment__why"(p_id bigint, p_depth int, p_seen text[], p_asker text[])
RETURNS SETOF text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE pad text := repeat('  ', p_depth); v_ok boolean; v_done boolean := false; v_t record;
        v_holds boolean := p_id IN (SELECT id FROM authz_int."file__comment");
BEGIN
  IF p_depth > 60 THEN RETURN NEXT pad || '...'; RETURN; END IF;
  RETURN NEXT pad || 'file.comment = folder.view';
  BEGIN
    v_ok := (p_id) IN (SELECT id FROM authz_int."file__folder__view");
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'folder.view';
    FOR v_t IN SELECT tg.id::text AS id, EXISTS (SELECT 1 FROM authz_int."folder__view" v WHERE v.id = tg.id) AS ok
               FROM (SELECT r."folder_id" AS id FROM "app"."files" r WHERE r."id" = p_id AND r."folder_id" IS NOT NULL) tg ORDER BY 2 DESC, 1 LIMIT 5 LOOP
      -- the walk stops at an object the one asking can't see: nothing about it, or above it
      IF NOT authz_int.asker_sees(p_asker, 'folder', v_t.id, false) THEN
        RETURN NEXT pad || '       ' || 'folder is a folder you can''t see';
        CONTINUE;
      END IF;
      RETURN NEXT pad || '  ' || CASE WHEN v_t.ok THEN 'yes  ' ELSE 'no   ' END || 'folder is folder '
                  || v_t.id || CASE WHEN v_t.ok THEN ', which has view' ELSE ', without view' END;
      IF NOT ('folder:view:' || v_t.id = ANY (p_seen)) AND ((v_t.ok AND v_ok AND NOT v_done) OR (NOT v_ok AND NOT v_t.ok AND p_depth < 5)) THEN
        v_done := true; RETURN QUERY SELECT * FROM authz_int."folder__view__why"(v_t.id::bigint, p_depth + 1 + 1, p_seen || ('folder:view:' || v_t.id), p_asker);
      END IF;
    END LOOP;
  END;
END $f$;

-- Everyone who holds a permission on an object: SELECT * FROM authz.who('folder', 3, 'view')
-- Candidates come from the data (a superset); each is checked as that user (the permission itself, authz_int.can).
CREATE OR REPLACE FUNCTION authz.who(p_type text, p_id text, p_perm text) RETURNS SETOF text
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_me text := coalesce(current_setting('authz.user_id', true), ''); v_c text;
        v_pt text := coalesce(current_setting('authz.principal_type', true), '');
        v_scopes text := coalesce(current_setting('authz.scopes', true), ''); v_bigint bigint;
BEGIN
  IF NOT authz_int.may_inspect(p_type, p_id) OR NOT authz_int.scope_perm(p_type, p_perm) THEN
    RAISE EXCEPTION 'you cannot see who has access to % %', p_type, p_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  -- (the caller's settings are put back below; an error needs nothing put back: Postgres undoes these settings with
  -- the transaction, or the savepoint the error is caught at, as for explain, check_invariants and the logins)
  PERFORM set_config('authz.scopes', '', true);   -- each candidate is checked with full rights
  PERFORM set_config('authz.principal_type', '', true);   -- candidates are users
  <<asking>> BEGIN
  CASE p_type
    WHEN 'user' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'bigint') THEN EXIT asking; END IF;
      v_bigint := p_id::bigint;
      CASE p_perm
        WHEN 'impersonate' THEN
          FOR v_c IN SELECT DISTINCT x::text FROM authz_int."user__impersonate__who"(v_bigint) x WHERE EXISTS (SELECT 1 FROM "app"."users" u WHERE u."id" = x) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz_int.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'org' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'bigint') THEN EXIT asking; END IF;
      v_bigint := p_id::bigint;
      RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
    WHEN 'team' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'bigint') THEN EXIT asking; END IF;
      v_bigint := p_id::bigint;
      RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
    WHEN 'folder' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'bigint') THEN EXIT asking; END IF;
      v_bigint := p_id::bigint;
      CASE p_perm
        WHEN 'share' THEN
          FOR v_c IN SELECT DISTINCT x::text FROM authz_int."folder__share__who"(v_bigint) x WHERE EXISTS (SELECT 1 FROM "app"."users" u WHERE u."id" = x) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz_int.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        WHEN 'edit' THEN
          FOR v_c IN SELECT DISTINCT x::text FROM authz_int."folder__edit__who"(v_bigint) x WHERE EXISTS (SELECT 1 FROM "app"."users" u WHERE u."id" = x) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz_int.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        WHEN 'view' THEN
          FOR v_c IN SELECT DISTINCT x::text FROM authz_int."folder__view__who"(v_bigint) x WHERE EXISTS (SELECT 1 FROM "app"."users" u WHERE u."id" = x) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz_int.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        WHEN 'break_glass' THEN
          FOR v_c IN SELECT DISTINCT x::text FROM authz_int."folder__break_glass__who"(v_bigint) x WHERE EXISTS (SELECT 1 FROM "app"."users" u WHERE u."id" = x) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz_int.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'file' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'bigint') THEN EXIT asking; END IF;
      v_bigint := p_id::bigint;
      CASE p_perm
        WHEN 'share' THEN
          FOR v_c IN SELECT DISTINCT x::text FROM authz_int."file__share__who"(v_bigint) x WHERE EXISTS (SELECT 1 FROM "app"."users" u WHERE u."id" = x) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz_int.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        WHEN 'comment' THEN
          FOR v_c IN SELECT DISTINCT x::text FROM authz_int."file__comment__who"(v_bigint) x WHERE EXISTS (SELECT 1 FROM "app"."users" u WHERE u."id" = x) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz_int.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        WHEN 'edit' THEN
          FOR v_c IN SELECT DISTINCT x::text FROM authz_int."file__edit__who"(v_bigint) x WHERE EXISTS (SELECT 1 FROM "app"."users" u WHERE u."id" = x) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz_int.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        WHEN 'view' THEN
          FOR v_c IN SELECT DISTINCT x::text FROM authz_int."file__view__who"(v_bigint) x WHERE EXISTS (SELECT 1 FROM "app"."users" u WHERE u."id" = x) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz_int.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    ELSE
      RAISE EXCEPTION 'no type % in the policy', p_type USING HINT = 'rowstile help AZ707';
  END CASE;
  END asking;
  PERFORM set_config('authz.user_id', v_me, true);
  PERFORM set_config('authz.principal_type', v_pt, true);
  PERFORM set_config('authz.scopes', v_scopes, true);
  PERFORM authz_int.sign();
END $f$;

-- Why the current user (or, for people who may inspect the object, another user) holds a
-- permission, or what is missing: SELECT * FROM authz.explain('file', 11, 'edit')
CREATE OR REPLACE FUNCTION authz.explain(p_type text, p_id text, p_perm text, p_user text DEFAULT NULL) RETURNS SETOF text
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_me text := coalesce(current_setting('authz.user_id', true), ''); v_ok boolean; v_bigint bigint;
        v_pt text := coalesce(current_setting('authz.principal_type', true), '');
        v_scopes text := coalesce(current_setting('authz.scopes', true), '');
        v_asker text[];   -- for another user: the one asking, whose sight the walk keeps to
BEGIN
  -- the signed-in user's own id is the signed-in user: asked as without it (a service whose id is a user's is not)
  IF p_user IS NOT NULL AND authz_int.canon('user', p_user) IS NOT DISTINCT FROM authz.uid()::text THEN
    p_user := NULL;
  END IF;
  -- another user's access: only for people who may inspect the object, within their scopes (as authz.who)
  IF p_user IS NOT NULL AND (NOT authz_int.may_inspect(p_type, p_id) OR NOT authz_int.scope_perm(p_type, p_perm)) THEN
    RAISE EXCEPTION 'you cannot inspect access to % %', p_type, p_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  -- people who can't see the object learn nothing about it, whatever else they hold on it (as for a missing one)
  IF p_user IS NULL AND NOT authz_int.may_inspect(p_type, p_id) AND NOT authz_int.visible(p_type, p_id) THEN
    RETURN NEXT 'no   you have no access to ' || p_type || ' ' || p_id;
    RETURN;
  END IF;
  IF p_user IS NOT NULL THEN
    v_asker := ARRAY[v_me, v_pt, v_scopes];
    PERFORM set_config('authz.user_id', authz_int.canon('user', p_user), true);
    PERFORM set_config('authz.principal_type', '', true);
    PERFORM set_config('authz.scopes', '', true);   -- that user's access, with full rights (as authz.who)
    PERFORM authz_int.sign();
  END IF;
  v_ok := authz_int.can(p_type, p_id, p_perm);
  RETURN NEXT CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || coalesce(coalesce(nullif(current_setting('authz.principal_type', true), ''), 'user') || ' ' || nullif(current_setting('authz.user_id', true), ''), 'nobody')
    || ' ' || CASE WHEN v_ok THEN 'holds ' ELSE 'does not hold ' END || p_perm || ' on ' || p_type || ' ' || p_id;
  <<asking>> BEGIN
  CASE p_type
    WHEN 'user' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'bigint') THEN EXIT asking; END IF;
      v_bigint := p_id::bigint;
      CASE p_perm
        WHEN 'impersonate' THEN RETURN QUERY SELECT * FROM authz_int."user__impersonate__why"(v_bigint, 1, '{}', v_asker);
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'org' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'bigint') THEN EXIT asking; END IF;
      v_bigint := p_id::bigint;
      RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
    WHEN 'team' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'bigint') THEN EXIT asking; END IF;
      v_bigint := p_id::bigint;
      RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
    WHEN 'folder' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'bigint') THEN EXIT asking; END IF;
      v_bigint := p_id::bigint;
      CASE p_perm
        WHEN 'share' THEN RETURN QUERY SELECT * FROM authz_int."folder__share__why"(v_bigint, 1, '{}', v_asker);
        WHEN 'edit' THEN RETURN QUERY SELECT * FROM authz_int."folder__edit__why"(v_bigint, 1, '{}', v_asker);
        WHEN 'view' THEN RETURN QUERY SELECT * FROM authz_int."folder__view__why"(v_bigint, 1, '{}', v_asker);
        WHEN 'break_glass' THEN RETURN QUERY SELECT * FROM authz_int."folder__break_glass__why"(v_bigint, 1, '{}', v_asker);
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'file' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'bigint') THEN EXIT asking; END IF;
      v_bigint := p_id::bigint;
      CASE p_perm
        WHEN 'share' THEN RETURN QUERY SELECT * FROM authz_int."file__share__why"(v_bigint, 1, '{}', v_asker);
        WHEN 'comment' THEN RETURN QUERY SELECT * FROM authz_int."file__comment__why"(v_bigint, 1, '{}', v_asker);
        WHEN 'edit' THEN RETURN QUERY SELECT * FROM authz_int."file__edit__why"(v_bigint, 1, '{}', v_asker);
        WHEN 'view' THEN RETURN QUERY SELECT * FROM authz_int."file__view__why"(v_bigint, 1, '{}', v_asker);
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    ELSE
      RAISE EXCEPTION 'no type % in the policy', p_type USING HINT = 'rowstile help AZ707';
  END CASE;
  END asking;
  PERFORM set_config('authz.user_id', v_me, true);
  PERFORM set_config('authz.principal_type', v_pt, true);
  PERFORM set_config('authz.scopes', v_scopes, true);
  PERFORM authz_int.sign();
END $f$;

