-- Privileges the policy doesn't give on rowstile's schemas and what is in them are taken back
DO $r$
DECLARE g record; v_taken int := 0;
BEGIN
  FOR g IN SELECT n.nspname::text AS object, gw.who, a.privilege_type AS privilege,
       format('REVOKE %s ON SCHEMA %I FROM %s CASCADE', a.privilege_type, n.nspname, gw.who) AS stmt
  FROM pg_namespace n, aclexplode(n.nspacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE n.nspname IN ('authz', 'authz_gen', 'authz_int') AND a.grantee <> n.nspowner
    AND NOT (a.grantee = '"app_user"'::regrole AND n.nspname <> 'authz_int' AND a.privilege_type = 'USAGE')
UNION ALL
SELECT c.oid::regclass::text, gw.who, a.privilege_type,
       format('REVOKE %s ON %s %s FROM %s CASCADE', a.privilege_type, CASE c.relkind WHEN 'S' THEN 'SEQUENCE' ELSE 'TABLE' END,
              c.oid::regclass, gw.who)
  FROM pg_class c, aclexplode(c.relacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE c.relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND a.grantee <> c.relowner
    AND NOT (a.grantee = '"app_user"'::regrole AND a.privilege_type = 'SELECT'
             AND c.relnamespace::regnamespace::text || '."' || replace(c.relname, '"', '""') || '"' = ANY (ARRAY['authz_gen."policy_lines"', 'authz_int."file__viewer"', 'authz_int."folder__edit"', 'authz_int."folder__editor"', 'authz_int."folder__linked_into__view"', 'authz_int."folder__share__direct"', 'authz_int."folder__view"', 'authz_int."folder__viewer"', 'authz_int."org__admin"']::text[]))
UNION ALL
SELECT format('%s (%I)', c.oid::regclass, att.attname), gw.who, a.privilege_type,
       format('REVOKE %s (%I) ON %s FROM %s CASCADE', a.privilege_type, att.attname, c.oid::regclass, gw.who)
  FROM pg_class c JOIN pg_attribute att ON att.attrelid = c.oid, aclexplode(att.attacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE c.relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND att.attacl IS NOT NULL
UNION ALL
SELECT p.oid::regprocedure::text, gw.who, a.privilege_type,
       format('REVOKE %s ON ROUTINE %s FROM %s CASCADE', a.privilege_type, p.oid::regprocedure, gw.who)
  FROM pg_proc p, aclexplode(p.proacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE p.pronamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND a.grantee <> p.proowner
    AND NOT (p.pronamespace = 'authz_int'::regnamespace AND a.grantee IN (0, '"app_user"'::regrole))
    AND NOT (p.pronamespace = 'authz_gen'::regnamespace AND a.grantee = '"app_user"'::regrole
             AND '"' || replace(p.proname, '"', '""') || '"' = ANY (ARRAY['"app.files:column folder_id after:items"', '"app.files:column folder_id after:why"', '"app.files:column id, owner_id, confidential:items"', '"app.files:column id, owner_id, confidential:why"', '"app.files:delete:items"', '"app.files:delete:why"', '"app.files:insert:items"', '"app.files:insert:refuse"', '"app.files:insert:why"', '"app.files:rules:explain"', '"app.files:update:items"', '"app.files:update:refuse"', '"app.files:update:why"', '"app.folders:column id, owner_id, org_id, inherit:items"', '"app.folders:column id, owner_id, org_id, inherit:why"', '"app.folders:column parent_id after:items"', '"app.folders:column parent_id after:why"', '"app.folders:delete:items"', '"app.folders:delete:why"', '"app.folders:insert:items"', '"app.folders:insert:refuse"', '"app.folders:insert:why"', '"app.folders:rules:explain"', '"app.folders:update:items"', '"app.folders:update:refuse"', '"app.folders:update:why"']::text[]))
    AND NOT (p.pronamespace = 'authz'::regnamespace AND a.grantee = '"app_user"'::regrole AND p.oid = ANY (ARRAY['authz.uid()', 'authz.principal()', 'authz.ctx(text)', 'authz.link_hashes()', 'authz.act_as(text, text)', 'authz.sign_out()', 'authz.connection_check()', 'authz.session_limited()', 'authz.can(text, text, text)', 'authz.list(text, text, text, integer)', 'authz.perms(text, text)', 'authz.perms_of(text, text[])', 'authz.share(text, text, text, text, text, text, timestamptz, timestamptz, text, jsonb)', 'authz.unshare(text, text, text, text, text, text)', 'authz.create_link(text, text, text, timestamptz)', 'authz.list_links(text, text)', 'authz.revoke_link(text, text, text)', 'authz.create_role(text, text, text, text, text[])', 'authz.set_role_permissions(bigint, text[])', 'authz.delete_role(bigint)', 'authz.roles_of(text, text)', 'authz.who(text, text, text)', 'authz.explain(text, text, text, text)', 'authz.list_shares(text, text)', 'authz.explain_rule(text, text, text, jsonb)', 'authz.who_among(text, text, text, text[], text)', 'authz.create_api_key(text, text, timestamptz, text, text)', 'authz.list_api_keys(text, text)', 'authz.revoke_api_key(bigint)', 'authz.login_key(text)', 'authz.login_jwt(text)', 'authz.view_as(text, text)', 'authz.request_access(text, text, text, text, interval)', 'authz.pending_requests()', 'authz.decide_request(bigint, boolean, text)', 'authz.cancel_request(bigint)', 'authz.break_glass(text, text, text, text, interval)', 'authz.start_review(text, text, timestamptz)', 'authz.review_items(bigint)', 'authz.review_decide(bigint, integer, boolean)', 'authz.close_review(bigint, boolean)', 'authz.who(text, bigint, text)', 'authz.explain(text, bigint, text, text)', 'authz.list_shares(text, bigint)', 'authz.list_links(text, bigint)', 'authz.revoke_link(text, bigint, text)', 'authz.create_link(text, bigint, text, timestamptz)', 'authz.create_role(text, bigint, text, text, text[])', 'authz.roles_of(text, bigint)', 'authz.request_access(text, bigint, text, text, interval)', 'authz.break_glass(text, bigint, text, text, interval)', 'authz.start_review(text, bigint, timestamptz)', 'authz.can(text, bigint, text)', 'authz.who_among(text, bigint, text, text[], text)', 'authz.perms(text, bigint)', 'authz.share(text, text, text, text, bigint, text, timestamptz, timestamptz, text, jsonb)', 'authz.unshare(text, text, text, text, bigint, text)', 'authz.share(text, bigint, text, text, text, text, timestamptz, timestamptz, text, jsonb)', 'authz.unshare(text, bigint, text, text, text, text)', 'authz.share(text, bigint, text, text, bigint, text, timestamptz, timestamptz, text, jsonb)', 'authz.unshare(text, bigint, text, text, bigint, text)']::regprocedure[])) LOOP
    EXECUTE g.stmt;
    v_taken := v_taken + 1;
  END LOOP;
  IF v_taken > 0 THEN
    RAISE WARNING 'took back % privileges on rowstile''s schemas that the policy doesn''t give (default privileges of the owner, or grants made since the last apply)', v_taken;
  END IF;
END $r$;

